::community_databricks_core::open_enum! {
    /// Compliance standard for SHIELD customers. See README.md for how instructions
    /// of how to add new standards.
    pub enum ComplianceStandard {
        /// `CANADA_PROTECTED_B`
        CanadaProtectedB => "CANADA_PROTECTED_B",
        /// `CYBER_ESSENTIAL_PLUS`
        CyberEssentialPlus => "CYBER_ESSENTIAL_PLUS",
        /// `FEDRAMP_HIGH`
        FedrampHigh => "FEDRAMP_HIGH",
        /// `FEDRAMP_IL5`
        FedrampIl5 => "FEDRAMP_IL5",
        /// `FEDRAMP_MODERATE`
        FedrampModerate => "FEDRAMP_MODERATE",
        /// `GERMANY_C5`
        GermanyC5 => "GERMANY_C5",
        /// `GERMANY_TISAX`
        GermanyTisax => "GERMANY_TISAX",
        /// `HIPAA`
        Hipaa => "HIPAA",
        /// `HITRUST`
        Hitrust => "HITRUST",
        /// `IRAP_PROTECTED`
        IrapProtected => "IRAP_PROTECTED",
        /// `ISMAP`
        Ismap => "ISMAP",
        /// `ITAR_EAR`
        ItarEar => "ITAR_EAR",
        /// `KSA_ECC_CCC_DCC`
        KsaEccCccDcc => "KSA_ECC_CCC_DCC",
        /// `K_FSI`
        KFsi => "K_FSI",
        /// `NONE`
        None => "NONE",
        /// `PCI_DSS`
        PciDss => "PCI_DSS",
    }
}

