    /// to be provided in `DELETE` requests (as a query parameter). The etag can be
    /// retrieved by making a `GET` request before the `DELETE` request. If the
    /// setting is updated/deleted concurrently, `DELETE` fails with 409 and the
    /// request must be retried by using the fresh etag in the 409 response.
    ///
    /// `DELETE /api/2.0/settings/types/default_namespace_ws/names/default`
    pub async fn delete(
        &self,
        request: DeleteDefaultNamespaceSettingRequest,
    ) -> ::community_databricks_core::Result<DeleteDefaultNamespaceSettingResponse> {
        let path = String::from("/api/2.0/settings/types/default_namespace_ws/names/default");
        let mut call = Call::new(Method::DELETE, path).workspace();
        call = call.query(query::field("etag", &request.etag)?);
        self.api
            .send::<DeleteDefaultNamespaceSettingResponse>(call)
            .await
    }

    /// Gets the default namespace setting.
    ///
    /// `GET /api/2.0/settings/types/default_namespace_ws/names/default`
    pub async fn get(
        &self,
        request: GetDefaultNamespaceSettingRequest,
    ) -> ::community_databricks_core::Result<DefaultNamespaceSetting> {
        let path = String::from("/api/2.0/settings/types/default_namespace_ws/names/default");
        let mut call = Call::new(Method::GET, path).workspace();
        call = call.query(query::field("etag", &request.etag)?);
        self.api.send::<DefaultNamespaceSetting>(call).await
    }

    /// Updates the default namespace setting for the workspace. A fresh etag needs
    /// to be provided in `PATCH` requests (as part of the setting field). The etag
    /// can be retrieved by making a `GET` request before the `PATCH` request. Note
