/// These APIs allow configuration of network settings for Databricks
/// workspaces by selecting which network policy to associate with the
/// workspace. Each workspace is always associated with exactly one network
/// policy that controls which network destinations can be accessed from the
/// Databricks environment. By default, workspaces are associated with the
/// 'default-policy' network policy. You cannot create or delete a
/// workspace's network option, only update it to associate the workspace
/// with a different policy
#[derive(Debug, Clone)]
pub struct WorkspaceNetworkConfigurationApi {
    api: ApiClient,
}

impl WorkspaceNetworkConfigurationApi {
    /// Wrap an [`ApiClient`].
    #[must_use]
    pub fn new(api: ApiClient) -> Self {
        Self { api }
    }

    /// Gets the network option for a workspace. Every workspace has exactly one
    /// network policy binding, with 'default-policy' used if no explicit assignment
    /// exists.
    ///
    /// `GET /api/2.0/accounts/{account_id}/workspaces/{workspace_id}/network`
    pub async fn get_workspace_network_option_rpc(
        &self,
        request: GetWorkspaceNetworkOptionRequest,
    ) -> ::community_databricks_core::Result<WorkspaceNetworkOption> {
        let path = format!(
            "/api/2.0/accounts/{}/workspaces/{}/network",
            path_param(self.api.account_id()?, false),
            path_param(&request.workspace_id.to_string(), false)
        );
        let call = Call::new(Method::GET, path);
        self.api.send::<WorkspaceNetworkOption>(call).await
    }

    /// Updates the network option for a workspace. This operation associates the
    /// workspace with the specified network policy. To revert to the default policy,
    /// specify 'default-policy' as the network_policy_id.
    ///
    /// `PUT /api/2.0/accounts/{account_id}/workspaces/{workspace_id}/network`
    pub async fn update_workspace_network_option_rpc(
        &self,
        request: UpdateWorkspaceNetworkOptionRequest,
    ) -> ::community_databricks_core::Result<WorkspaceNetworkOption> {
        let path = format!(
            "/api/2.0/accounts/{}/workspaces/{}/network",
            path_param(self.api.account_id()?, false),
            path_param(&request.workspace_id.to_string(), false)
        );
        let mut call = Call::new(Method::PUT, path);
        call = call.json(&request.workspace_network_option)?;
        self.api.send::<WorkspaceNetworkOption>(call).await
    }
}
